final class SupplierInlineContactEntryType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('firstName',TextType::class,['label'=>'Nombre(s)'])->add('lastName',TextType::class,['label'=>'Apellidos','required'=>false])->add('personalEmail',EmailType::class,['label'=>'Correo personal','required'=>false])->add('businessEmail',EmailType::class,['label'=>'Correo laboral','required'=>false])->add('birthDate',DateType::class,['label'=>'Cumpleaños','required'=>false,'widget'=>'single_text','input'=>'datetime_immutable'])->add('department',TextType::class,['label'=>'Departamento','required'=>false])->add('position',TextType::class,['label'=>'Puesto','required'=>false])->add('workDays',TextType::class,['label'=>'Días de atención','required'=>false])->add('workHours',TextType::class,['label'=>'Horario','required'=>false])->add('notes',TextareaType::class,['label'=>'Notas','required'=>false])->add('isPrimary',CheckboxType::class,['label'=>'Contacto principal','required'=>false])->add('canSellProducts',CheckboxType::class,['label'=>'Puede ofrecer productos','required'=>false])->add('phones',CollectionType::class,['label'=>'Teléfonos y fax','entry_type'=>ClientPhoneEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype_name'=>'__supplier_contact_phone__']);}public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>SupplierInlineContactData::class]);}}
